//! Vectors for LINK's public shape, messages, key faults, column lists and equality row
//! (`blocks/iop/link.h`), and for member.h's claims, stretched weights and row checks, generated by
//! `scripts/cpp_vectors/link_member_vectors.cpp`.
//!
//! The test keeps the C++ tool's names `S` and `L`; `non_snake_case` is allowed for that reason.

#![allow(non_snake_case)]

use std::collections::HashMap;
use std::rc::Rc;

use fp_core::code::code::Code;
use fp_core::field::ext::{F, E};
use fp_core::hash::modes::Digest;
use fp_core::iop::batt::TensorRow;
use fp_core::iop::context::OracleNotice;
use fp_core::iop::foldeq::{vector_lay, FoldedRow, IndexKey, IndexReader, IndexRecord, IndexShape};
use fp_core::iop::iopp::{IoppChoice, IoppStage};
use fp_core::iop::link::{
    link_equality_row, link_fault, link_fold_shape, link_key_fault, link_lists, link_message,
    public_fault, LinkShape, LINK_LABEL,
};
use fp_core::iop::lin::LinShape;
use fp_core::iop::mask::{receipt_for_a_test, MaskLedger, MaskTerm};
use fp_core::iop::member::{
    member_claim, member_inner, member_pending_row, member_rows_fit, member_weights_on_rows,
};
use fp_core::iop::relation::{Codes, OracleShape, Part, Statement};
use fp_core::iop::tensor::Tensor;
use fp_core::numbers::plan::TableDistances;
use fp_core::tree::positions::PositionList;

const VECTORS: &str = include_str!("../../fixtures/link_member_vectors.txt");

// ------------------------------------------------------------------------------------------------
// The fixture's shape
// ------------------------------------------------------------------------------------------------

struct Fixture<'a> {
    lines: std::str::Lines<'a>,
    number: usize,
}

impl<'a> Fixture<'a> {
    fn new(text: &'a str) -> Self {
        Fixture { lines: text.lines(), number: 0 }
    }

    /// The next line, which must begin with `prefix`.
    fn next(&mut self, prefix: &str) -> &'a str {
        let line = self.lines.next().expect("the fixture ended early");
        self.number += 1;
        assert!(
            line.starts_with(prefix),
            "line {}: expected {:?}, found {:?}",
            self.number,
            prefix,
            line
        );
        line
    }

    fn at_end(&mut self) {
        if let Some(line) = self.lines.next() {
            panic!("line {}: the fixture has another line: {:?}", self.number + 1, line);
        }
    }
}

/// The whitespace-separated `key=value` tokens of one line. Values must not contain spaces (names
/// and faults do, and are read by `after`/`upto` instead).
fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}

/// What follows `key` in the line, to its end.
fn after<'a>(line: &'a str, key: &str) -> &'a str {
    let at = line
        .find(key)
        .unwrap_or_else(|| panic!("no {:?} in {:?}", key, line));
    &line[at + key.len()..]
}

/// The first whitespace-separated token of `s`.
fn token(s: &str) -> &str {
    s.split_whitespace().next().unwrap_or_else(|| panic!("no token in {:?}", s))
}

/// The prefix of `s` before the first of `stops`.
fn upto<'a>(s: &'a str, stops: &[&str]) -> &'a str {
    let mut end = s.len();
    for stop in stops {
        if let Some(i) = s.find(stop) {
            end = end.min(i);
        }
    }
    s[..end].trim()
}

fn number<T: std::str::FromStr>(s: &str) -> T
where
    T::Err: std::fmt::Debug,
{
    s.parse().unwrap()
}

fn f(s: &str) -> F {
    F(u64::from_str_radix(s, 16).unwrap())
}

fn e(s: &str) -> E {
    let p: Vec<&str> = s.split(',').collect();
    assert_eq!(p.len(), 3, "E {}", s);
    E([f(p[0]), f(p[1]), f(p[2])])
}

fn eseq(s: &str) -> Vec<E> {
    s.split(';').map(e).collect()
}

fn u64s(s: &str) -> Vec<u64> {
    s.split(',').map(|x| x.parse().unwrap()).collect()
}

fn u32s(s: &str) -> Vec<u32> {
    s.split(',').map(|x| x.parse().unwrap()).collect()
}

fn stage(s: &str) -> IoppStage {
    let p: Vec<u32> = s.split(':').map(|x| x.parse().unwrap()).collect();
    assert_eq!(p.len(), 4, "stage {}", s);
    IoppStage { code: p[0], mask_code: p[1], k: p[2], h: p[3] }
}

fn stages(s: &str) -> Vec<IoppStage> {
    s.split(';').map(stage).collect()
}

fn stages_text(v: &[IoppStage]) -> String {
    v.iter()
        .map(|s| format!("{}:{}:{}:{}", s.code, s.mask_code, s.k, s.h))
        .collect::<Vec<_>>()
        .join(";")
}

/// An oracle shape from the rest of a `SIDE_U` or `NOTICE` line (after the prefix).
fn oracle_shape(rest: &str) -> OracleShape {
    OracleShape {
        name: upto(after(rest, "name="), &[" code="]).to_string(),
        code: number(token(after(rest, " code="))),
        main_rows: number(token(after(rest, " main_rows="))),
        main_deg: number(token(after(rest, " main_deg="))),
        mask_rows: number(token(after(rest, " mask_rows="))),
        mask_code: number(token(after(rest, " mask_code="))),
        answers: number(token(after(rest, " answers="))),
    }
}

/// The value of an option of a fault, with the fixture's word for nothing.
fn shown(fault: Option<&str>) -> &str {
    fault.unwrap_or("none")
}

/// The C++ tool's `e(x)`: the coordinates x, x + 1 and x + 2.
fn eu(x: u64) -> E {
    E([F(x), F(x + 1), F(x + 2)])
}

/// `digest_with` of the C++ tool.
fn digest_with(x: u64) -> Digest {
    let mut d = Digest::zero();
    for i in 0..8 {
        d.w[i] = (x + i as u64) as u32;
    }
    d
}

/// The `T kind=<kind> i=<i> ...` line of one tensor.
fn check_tensor(line: &str, kind: &str, i: usize, t: &Tensor) {
    let f = fields(line);
    assert_eq!(f["kind"], kind);
    assert_eq!(number::<u64>(f["i"]), i as u64);
    assert_eq!(number::<u32>(f["vars"]), t.vars());
    let dense: Vec<u32> = if f["dense"] == "none" {
        assert!(t.dense_vars.is_empty(), "{} tensor {} has dense variables", kind, i);
        Vec::new()
    } else {
        u32s(f["dense"])
    };
    assert_eq!(t.dense_vars, dense);
    assert_eq!(t.scalar, e(f["scalar"]));
    let at = eseq(f["at"]);
    let n = 1u64 << t.vars();
    assert_eq!(at.len() as u64, n, "{} tensor {} entry count", kind, i);
    for j in 0..n {
        assert_eq!(t.at(j), at[j as usize], "{} tensor {} entry {}", kind, i, j);
    }
}

// ------------------------------------------------------------------------------------------------
// The vectors
// ------------------------------------------------------------------------------------------------

#[test]
fn link_member_vectors_match_the_cpp_reference() {
    let mut r = Fixture::new(VECTORS);

    // The label and the shape. `link_table` and `link_codes` in the C++ tool hold the parts of
    // these inputs that the fixture does not print; the rest is taken from the fixture itself.
    {
        let line = r.next("LABEL ");
        let got = u64::from_str_radix(fields(line)["link"], 16).unwrap();
        assert_eq!(got, LINK_LABEL);
    }

    let mut codes = Codes::default();
    codes.base.push(Code { log_n: 6, ell: 8, r: 1 });
    codes.mask.push(Code { log_n: 6, ell: 8, r: 1 });
    codes.mask.push(Code { log_n: 6, ell: 32, r: 1 });

    let mut S = LinkShape::default();
    {
        let line = r.next("SHAPE ");
        let f = fields(line);
        S.table = IndexShape {
            code: Code { log_n: 5, ell: 8, r: 2 },
            v: number(f["v"]),
            answers: 1,
            salt_bytes: 40,
            distances: TableDistances { radius: 1, later_radius: 2, m_once: 3, m_later: 4 },
        };
        S.columns_first = number(f["columns_first"]);
        S.columns_further = number(f["columns_further"]);
        S.code = number(f["code"]);
        S.mask_code = number(f["mask_code"]);
        S.rows = number(f["rows"]);
        S.rows_high = f["rows_high"] == "1";
        S.leaf_class = number(f["leaf_class"]);
        S.masks_ahead = f["masks_ahead"] == "1";
        let test = stages(f["later"]);
        S.later = test[1..].to_vec();
        S.choice = IoppChoice { masks_ride: true };

        assert_eq!(S.v(), number::<u32>(f["v"]));
        assert_eq!(S.entry_bits(), number::<u32>(f["entry_bits"]));
        assert_eq!(S.cut(), number::<u64>(f["cut"]));
        assert_eq!(S.rows, number::<u64>(f["rows"]));
        assert_eq!(S.columns_first, number::<u64>(f["columns_first"]));
        assert_eq!(S.columns_further, number::<u64>(f["columns_further"]));
        assert_eq!(S.code, number::<u32>(f["code"]));
        assert_eq!(S.mask_code, number::<u32>(f["mask_code"]));
        assert_eq!(S.rows_high, f["rows_high"] == "1");
        assert_eq!(S.leaf_class, number::<u32>(f["leaf_class"]));
        assert_eq!(S.masks_ahead, f["masks_ahead"] == "1");
        assert_eq!(stages_text(&S.test()), f["later"]);
    }

    // The two folded rows' shapes; the sample count is the answer count on the first `SIDE_U`.
    let samples: u32;
    {
        let line = r.next("SIDE first ");
        let side = fields(line);
        let uline = r.next("SIDE_U ");
        let u = oracle_shape(uline);
        samples = u.answers;
        let s = S.first(samples);
        assert_eq!(s.columns, number::<u64>(side["columns"]));
        assert_eq!(s.entries(), number::<u64>(side["entries"]));
        assert_eq!(s.tail_first(), number::<u64>(side["tail_first"]));
        assert_eq!(s.u, u);
    }
    {
        let line = r.next("SIDE further ");
        let side = fields(line);
        let uline = r.next("SIDE_U ");
        let u = oracle_shape(uline);
        let s = S.further(samples);
        assert_eq!(s.columns, number::<u64>(side["columns"]));
        assert_eq!(s.entries(), number::<u64>(side["entries"]));
        assert_eq!(s.tail_first(), number::<u64>(side["tail_first"]));
        assert_eq!(s.u, u);
    }

    // The fault cases, one changed field each. The mutation is the one that the C++ tool makes.
    for _ in 0..9 {
        let line = r.next("FAULT ");
        let name = upto(after(line, "name="), &[" public="]);
        let public = upto(after(line, " public="), &[" link="]);
        let link = after(line, " link=").trim();
        let (public_got, link_got): (Option<&str>, Option<&str>) = match name {
            "valid" => (public_fault(&S), link_fault(&codes, &S, samples)),
            "no_column" => {
                let mut x = S.clone();
                x.columns_first = 0;
                (public_fault(&x), link_fault(&codes, &x, samples))
            }
            "no_rows" => {
                let mut x = S.clone();
                x.rows = 0;
                (public_fault(&x), link_fault(&codes, &x, samples))
            }
            "one_stage" => {
                let mut x = S.clone();
                x.later.clear();
                (public_fault(&x), link_fault(&codes, &x, samples))
            }
            "no_answers" => {
                let mut x = S.clone();
                x.table.answers = 0;
                (public_fault(&x), link_fault(&codes, &x, samples))
            }
            "no_mask_code" => {
                let mut x = S.clone();
                x.mask_code = 2;
                (public_fault(&x), link_fault(&codes, &x, samples))
            }
            "no_code" => {
                let mut x = S.clone();
                x.code = 3;
                (public_fault(&x), link_fault(&codes, &x, samples))
            }
            "last_stage_rows" => {
                let mut x = S.clone();
                x.later[0].k = 1;
                (public_fault(&x), link_fault(&codes, &x, samples))
            }
            "mask_too_short" => {
                let mut c = codes.clone();
                c.mask[0].ell = 4;
                (public_fault(&S), link_fault(&c, &S, samples))
            }
            other => panic!("no such fault case: {}", other),
        };
        assert_eq!(shown(public_got), public, "fault case {}", name);
        assert_eq!(shown(link_got), link, "fault case {}", name);
    }

    // The oracle messages before the test, and the mask's fold shape.
    {
        let line = r.next("MESSAGE ");
        let f = fields(line);
        assert_eq!(S.masks_ahead as u64, number::<u64>(f["masks_ahead"]));
        let m = link_message(&S, samples);
        assert_eq!(m.len() as u64, number::<u64>(f["count"]));
        for notice in &m {
            let line = r.next("NOTICE ");
            let rest = &line["NOTICE ".len()..];
            let want = OracleNotice {
                shape: oracle_shape(rest),
                leaf_class: number(token(after(rest, " leaf="))),
            };
            assert_eq!(notice.shape, want.shape);
            assert_eq!(notice.leaf_class, want.leaf_class);
        }

        let line = r.next("FOLD ");
        let f = fields(line);
        let fold_shape = link_fold_shape(&S);
        assert_eq!(fold_shape.code, number::<u32>(f["code"]));
        assert_eq!(fold_shape.mask_code, number::<u32>(f["mask_code"]));
        assert_eq!(fold_shape.layout.k, number::<u32>(f["k"]));
        assert_eq!(fold_shape.layout.h, number::<u32>(f["h"]));
        assert_eq!(fold_shape.layout.members.len() as u64, number::<u64>(f["members"]));
        assert_eq!(fold_shape.mask_leaf_class, number::<u32>(f["mask_leaf"]));
        assert_eq!(fold_shape.keep_folded_coefficients, f["keep"] == "1");
        assert_eq!(fold_shape.folded_coefficients_alone, f["alone"] == "1");
        assert_eq!(fold_shape.target_from_the_rounds, f["target"] == "1");

        let line = r.next("MESSAGE_NO_MASK ");
        let f = fields(line);
        let mut q = S.clone();
        q.masks_ahead = false;
        assert_eq!(link_message(&q, samples).len() as u64, number::<u64>(f["count"]));
    }

    // link_key_fault on the five hand-built keys.
    {
        let configuration = digest_with(7);
        let root = digest_with(11);
        let mut rec = IndexRecord::default();
        rec.y = vec![eu(600); S.table.rows() as usize * S.table.answers as usize];
        for _ in 0..5 {
            let line = r.next("KEY ");
            let name = upto(after(line, "name="), &[" fault="]);
            let fault = upto(after(line, " fault="), &[" link="]);
            let link = after(line, " link=").trim();
            let key = match name {
                "good" => IndexKey::new(S.table.clone(), &configuration, &root, rec.clone()),
                "other_shape" => {
                    let mut t = S.table.clone();
                    t.v = 3;
                    let mut y = Vec::new();
                    for _ in 0..(t.rows() as usize * t.answers as usize) {
                        y.push(eu(601));
                    }
                    IndexKey::new(t, &configuration, &root, IndexRecord { y })
                }
                "other_configuration" => {
                    IndexKey::new(S.table.clone(), &digest_with(8), &root, rec.clone())
                }
                "short_record" => {
                    let mut y = rec.clone();
                    y.y.pop();
                    IndexKey::new(S.table.clone(), &configuration, &root, y)
                }
                "no_answers" => {
                    let mut t = S.table.clone();
                    t.answers = 0;
                    IndexKey::new(t, &configuration, &root, IndexRecord { y: Vec::new() })
                }
                other => panic!("no such key case: {}", other),
            };
            assert_eq!(shown(key.fault()), fault, "key case {}", name);
            assert_eq!(shown(link_key_fault(&configuration, &S.table, &key)), link, "key case {}", name);
        }
    }

    // The positions of the link round, split between the tables.
    {
        let line = r.next("LISTS ");
        let f = fields(line);
        let log_n = number::<u32>(f["log_n"]);
        let drawn = PositionList::from_draws(vec![17, 3, 9, 3, 21], log_n);
        assert_eq!(drawn.log_n(), log_n);
        assert_eq!(drawn.draws().len() as u64, number::<u64>(f["draws"]));
        let lists = link_lists(&S, &drawn);
        for side in 0..2 {
            let line = r.next("LIST ");
            let f = fields(line);
            assert_eq!(number::<u64>(f["side"]), side);
            let p = if side == 0 { &lists.first } else { &lists.further };
            assert_eq!(p.log_n(), number::<u32>(f["log_n"]));
            assert_eq!(p.size() as u64, number::<u64>(f["size"]));
            assert_eq!(p.draws(), u64s(f["draws"]).as_slice());
            assert_eq!(p.all(), u64s(f["all"]).as_slice());
        }
    }

    // The equality row and every coefficient of it.
    {
        let line = r.next("EQ ");
        let name = upto(after(line, "name="), &[" target="]);
        let f = fields(line);
        let lay = vector_lay(&codes, &S.first(samples).u, S.rows_high);
        let first = FoldedRow { oracle: 0, lay };
        let further = FoldedRow { oracle: 1, lay };
        let phi = {
            let raw = eseq(f["phi"]);
            assert_eq!(raw.len(), S.entry_bits() as usize);
            raw
        };
        let row = link_equality_row(&S, &phi, &first, &further, S.cut());
        assert_eq!(row.name, name);
        assert_eq!(row.target, e(f["target"]));
        assert_eq!(row.terms.len() as u64, number::<u64>(f["terms"]));
        assert_eq!(row.units.len() as u64, number::<u64>(f["units"]));
        assert_eq!(row.runs.len() as u64, number::<u64>(f["runs"]));
        assert_eq!(row.forms.len() as u64, number::<u64>(f["forms"]));
        assert_eq!(lay.row_bits, number::<u32>(f["lay_row_bits"]));
        assert_eq!(lay.place_bits, number::<u32>(f["lay_place_bits"]));
        assert_eq!(lay.rows_high, f["lay_rows_high"] == "1");
        for side in 0..2u32 {
            for j in 0..(1u64 << lay.bits()) {
                let line = r.next("EQVAL ");
                let f = fields(line);
                assert_eq!(number::<u32>(f["side"]), side);
                assert_eq!(number::<u64>(f["j"]), j);
                assert_eq!(
                    row.coefficient(side, Part::Main, j),
                    e(f["coeff"]),
                    "equality row side {} entry {}",
                    side,
                    j
                );
            }
        }
    }

    // stretch_in_the_cube on a shared vector.
    {
        let line = r.next("STRETCH ");
        let f = fields(line);
        let k_row = number::<u32>(f["k_row"]);
        let first_row = number::<u64>(f["first_row"]);
        let values = Rc::new(eseq(f["values"]));
        let g = member_inner::stretch_in_the_cube(k_row, first_row, values);
        assert_eq!(g.len() as u64, number::<u64>(f["tensors"]));
        for i in 0..g.len() {
            let line = r.next("T ");
            check_tensor(line, "stretch", i, &g[i]);
        }
    }

    // member_weights_on_rows: the same through a LIN shape, ending at the matrix's last row.
    {
        let line = r.next("WEIGHTS ");
        let f = fields(line);
        let mut L = LinShape::default();
        L.matrix_rows = number(f["matrix_rows"]);
        L.k_lo = 1;
        L.fold.index.v = 2;
        let values = Rc::new(eseq(f["values"]));
        let g = member_weights_on_rows(&L, 2, values);
        assert_eq!(L.matrix_rows, number::<u64>(f["matrix_rows"]));
        assert_eq!(L.k_row(), number::<u32>(f["k_row"]));
        assert_eq!(L.k_col(), number::<u32>(f["k_col"]));
        assert_eq!(g.len() as u64, number::<u64>(f["tensors"]));
        for i in 0..g.len() {
            let line = r.next("T ");
            check_tensor(line, "weights", i, &g[i]);
        }
    }

    // A pending claim, member_pending_row's form of it, and member_claim's.
    let phi2 = vec![eu(2), eu(3)];
    let psi = vec![eu(301), eu(302), eu(303)];
    let target = eu(400);
    let dense = {
        let mut t = Tensor::default();
        t.push_dense(1);
        t.insert_choice(1, 1, 1);
        t.set_values(Rc::new(vec![eu(201), eu(202)]), 0);
        t
    };
    let mut ledger = MaskLedger::new(receipt_for_a_test(0, 0, 4, 1, 0));

    {
        let line = r.next("ROW ");
        let f = fields(line);
        assert_eq!(target, e(f["target"]));
        assert_eq!(psi, eseq(f["psi"]));
        let eq = Tensor::eq(&phi2, 2, E::one());
        let line = r.next("T ");
        check_tensor(line, "row", 0, &eq);
        let line = r.next("T ");
        check_tensor(line, "row", 1, &dense);
    }

    {
        let line = r.next("PENDING ");
        let f = fields(line);
        let row = member_pending_row(
            vec![Tensor::eq(&phi2, 2, E::one()), dense.clone()],
            psi.clone(),
            ledger.take(),
            eu(31),
            target,
        );
        assert_eq!(row.target, e(f["target"]));
        assert_eq!(row.psi, eseq(f["psi"]));
        assert_eq!(row.masks.len() as u64, number::<u64>(f["masks"]));
        let line = r.next("PENDING_MASK ");
        let f = fields(line);
        assert_eq!(number::<u64>(f["i"]), 0);
        assert_eq!(row.masks[0].slot.oracle(), number::<u32>(f["oracle"]));
        assert_eq!(Part::Mask as u32, number::<u32>(f["part"]));
        assert_eq!(row.masks[0].slot.index(), number::<u32>(f["index"]));
        assert_eq!(row.masks[0].coeff, e(f["coeff"]));
        for i in 0..row.g.len() {
            let line = r.next("T ");
            check_tensor(line, "pending", i, &row.g[i]);
        }
    }

    {
        let line = r.next("CLAIM ");
        let f = fields(line);
        let row = TensorRow {
            g: vec![Tensor::eq(&phi2, 2, E::one()), dense.clone()],
            psi: psi.clone(),
            masks: vec![
                MaskTerm { slot: ledger.take(), coeff: eu(21) },
                MaskTerm { slot: ledger.take(), coeff: eu(22) },
            ],
            target,
        };
        let claim = member_claim(row);
        assert_eq!(claim.target, e(f["target"]));
        assert_eq!(claim.psi, eseq(f["psi"]));
        assert_eq!(claim.g.len() as u64, number::<u64>(f["g"]));
        assert_eq!(claim.masks.len() as u64, number::<u64>(f["masks"]));
        for i in 0..claim.g.len() {
            let line = r.next("T ");
            check_tensor(line, "claim", i, &claim.g[i]);
        }
        for i in 0..claim.masks.len() {
            let line = r.next("CLAIM_MASK ");
            let f = fields(line);
            let m = &claim.masks[i];
            assert_eq!(number::<u64>(f["i"]), i as u64);
            assert_eq!(m.oracle, number::<u32>(f["oracle"]));
            assert_eq!(m.part as u32, number::<u32>(f["part"]));
            assert_eq!(m.index, number::<u64>(f["index"]));
            assert_eq!(m.coeff, e(f["coeff"]));
        }
    }

    // member_rows_fit on a small statement.
    {
        let line = r.next("ROWS_FIT ");
        let f = fields(line);
        let mut st = Statement::new(codes.clone());
        let mut masks = OracleShape::default();
        masks.name = "index masks".into();
        masks.main_rows = 0;
        masks.mask_rows = 2;
        masks.mask_code = 0;
        masks.answers = 1;
        let index_masks = st.sent(masks);

        let mut L = LinShape::default();
        L.matrix_rows = 3;
        L.k_lo = 1;
        L.fold.index.v = 2;
        L.own_mask_code = 0;

        let mut ledger = MaskLedger::new(receipt_for_a_test(index_masks, 0, 8, 1, 0));
        let mut pending = Vec::new();
        for i in 0..2u64 {
            pending.push(TensorRow {
                g: vec![Tensor::eq(&phi2, 2, E::one())],
                psi: vec![eu(701), eu(702), eu(703)],
                masks: vec![MaskTerm { slot: ledger.take(), coeff: eu(710 + i) }],
                target: eu(700 + i),
            });
        }
        member_rows_fit(&st, &L, index_masks, &pending);
        assert_eq!(index_masks as u64, number::<u64>(f["index_masks"]));
        assert_eq!(pending.len() as u64, number::<u64>(f["rows"]));
        assert_eq!(L.k_col() as u64, number::<u64>(f["k_col"]));
        assert_eq!(L.k_row() as u64, number::<u64>(f["k_row"]));
        assert_eq!(f["ok"], "1");
    }

    r.at_end();
}
